import java.util.Scanner;

public class Main {
    static long MAX_INF = 17446744073709551616L;
    static long modulus, sizeN, sizeK;
    static long[][] dpTable = new long[19][300005];
    static long[] factorial = new long[300005], invFactor = new long[300005];

    static long fast_pow(long base, long exponent) {
        long result = 1L;
        while (exponent > 0) {
            if ((exponent & 1L) == 1L) result = (result * base) % modulus;
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return result;
    }

    static long nCr(int a, int b) {
        return (((factorial[a] * invFactor[b]) % modulus) * invFactor[a - b]) % modulus;
    }

    static long solve() {
        int i, j, mask;
        factorial[0] = 1L;
        long limit = Math.max(sizeN, sizeK);
        for (i = 1; i <= limit; i++) {
            factorial[i] = (factorial[i - 1] * i) % modulus;
        }
        invFactor[(int)limit] = fast_pow(factorial[(int)limit], modulus - 2);
        for (i = (int)limit - 1; i >= 0; i--) {
            invFactor[i] = (invFactor[i + 1] * (i + 1)) % modulus;
        }
        for (i = 1; i <= sizeN; i++) {
            dpTable[1][i] = invFactor[i];
        }
        long total = (dpTable[1][(int)sizeN] * nCr((int)sizeK, 1)) % modulus;
        int maxIter = (int)Math.min(18, sizeK);
        for (i = 2; i <= maxIter; i++) {
            for (j = (int)sizeN; j > 0; j = (j - 1) & (int)sizeN) {
                if (dpTable[i - 1][j] == 0) continue;
                int remaining = (int)(sizeN ^ j);
                for (mask = remaining; mask > j; mask = (mask - 1) & remaining) {
                    dpTable[i][j ^ mask] += dpTable[i - 1][j] * invFactor[mask];
                    if (dpTable[i][j ^ mask] > MAX_INF) dpTable[i][j ^ mask] %= modulus;
                }
            }
            for (j = (int)sizeN; j > 0; j = (j - 1) & (int)sizeN) {
                if (dpTable[i][j] >= modulus) dpTable[i][j] %= modulus;
            }
            long res = (dpTable[i][(int)sizeN] * nCr(i, (int)sizeK)) % modulus;
            res = (res * factorial[i]) % modulus;
            total = (total + res) >= modulus ? (total + res - modulus) : (total + res);
        }
        total = (total * factorial[(int)sizeN]) % modulus;
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        sizeN = sc.nextLong();
        sizeK = sc.nextLong();
        modulus = sc.nextLong();
        long answer = fast_pow(sizeK, sizeN);
        if (sizeN % 2 == 0) answer = (answer - solve() + modulus) % modulus;
        System.out.println(answer);
        sc.close();
    }
